module {
  func.func @main(
    %arg0: tensor<6x6x3x3x3xf32>,   // conv_transpose3d.weight [out_c, in_c, kD, kH, kW]
    %arg1: tensor<8x6x7x7x7xf32>    // input [N, in_c, D, H, W]
  ) -> tensor<8x6x9x9x9xf32> {
    // PyTorch ConvTranspose3d expects weight [out_c, in_c, kD, kH, kW]
    // StableHLO expects kernel [out_c, in_c, ...], but for transposed conv, we must swap in_c and out_c
    // and reverse spatial dims.

    // 1. Swap in_c and out_c: [6,6,3,3,3] -> [6,6,3,3,3] (no-op since both are 6, but must permute for generality)
    %w_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<6x6x3x3x3xf32>) -> tensor<6x6x3x3x3xf32>

    // 2. Reverse spatial dims for transposed convolution
    %w_tr = "stablehlo.reverse"(%w_t) {dimensions = array<i64: 2, 3, 4>} : (tensor<6x6x3x3x3xf32>) -> tensor<6x6x3x3x3xf32>

    // 3. Convolution with correct dimension_numbers
    // input:   [N, in_c, D, H, W] = [8, 6, 7, 7, 7]
    // kernel:  [in_c, out_c, kD, kH, kW] = [6, 6, 3, 3, 3]
    // output:  [N, out_c, D_out, H_out, W_out] = [8, 6, 9, 9, 9]
    // dimension_numbers: input [b, f, 0, 1, 2], kernel [i, o, 0, 1, 2], output [b, o, 0, 1, 2]
    // feature_group_count = 1

    %result = "stablehlo.convolution"(%arg1, %w_tr) {
      window_strides = array<i64: 1, 1, 1>,
      padding = dense<[[2, 2], [2, 2], [2, 2]]> : tensor<3x2xi64>,
      lhs_dilation = array<i64: 1, 1, 1>,
      rhs_dilation = array<i64: 1, 1, 1>,
      dimension_numbers = #stablehlo.conv<[
        b, f, 0, 1, 2
      ]x[
        i, o, 0, 1, 2
      ]->[
        b, o, 0, 1, 2
      ]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<8x6x7x7x7xf32>, tensor<6x6x3x3x3xf32>) -> tensor<8x6x9x9x9xf32>

    return %result : tensor<8x6x9x9x9xf32>
  }
}
