    %arg2: tensor<16xf32>,              // conv_transpose.bias (shape [out_c])
    %arg3: tensor<6x3x16x7x7xf32>       // input (shape [N, in_c, D, H, W])
  ) -> tensor<6x1x31x13x13xf32> {
    // 1. ConvTranspose3d (input: [N, in_c, D, H, W], weight: [in_c, out_c, kD, kH, kW])
    // PyTorch weight: [in_c, out_c, kD, kH, kW]
    // StableHLO expects: lhs=input [N, C, D, H, W], rhs=kernel [O, I, kD, kH, kW]
    // So we need to transpose weight from [in_c, out_c, kD, kH, kW] to [out_c, in_c, kD, kH, kW]
    %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

