func.func @main(%x: tensor<3x3xf32>) -> tensor<3x3xf32> {
  // Create iota along rows (i): shape [3,3], values [[0,0,0],[1,1,1],[2,2,2]]
  %i = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<3x3xi32>
  // Create iota along columns (j): shape [3,3], values [[0,1,2],[0,1,2],[0,1,2]]
  %j = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<3x3xi32>
  // Compare j <= i (elementwise)
  %mask = "stablehlo.compare"(%j, %i) {comparison_direction = #stablehlo<comparison_direction LE>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<3x3xi32>, tensor<3x3xi32>) -> tensor<3x3xi1>
  // Constant 0.0 tensor
  %zero = stablehlo.constant dense<0.0> : tensor<3x3xf32>
  // Select: if mask true, take x, else 0.0
  %out = "stablehlo.select"(%mask, %x, %zero) : (tensor<3x3xi1>, tensor<3x3xf32>, tensor<3x3xf32>) -> tensor<3x3xf32>
  return %out : tensor<3x3xf32>
}
