func.func @main(%x: tensor<4x8xf32>) -> tensor<4x8xf32> {
  // Compute exp(x)
  %exp_x = stablehlo.exponential %x : tensor<4x8xf32>

  // Create a scalar zero for the reduce init value
  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  // Sum over dimension 1 (the 8 columns) to get sum_k exp(x[i, k]) for each i
  %sum_exp = "stablehlo.reduce"(%exp_x, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<4x8xf32>, tensor<f32>) -> tensor<4xf32>

  // Broadcast sum_exp from shape [4] to [4,8] along dimension 0
  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0>} : (tensor<4xf32>) -> tensor<4x8xf32>

  // Divide exp(x) by sum_exp_bcast to get softmax
  %softmax = stablehlo.divide %exp_x, %sum_exp_bcast : tensor<4x8xf32>

  return %softmax : tensor<4x8xf32>
}
