func.func @main(
    %arg0: tensor<6x1x1xf32>,      // multiplier
    %arg1: tensor<6x6x3x3xf32>,    // conv.weight
    %arg2: tensor<6xf32>,          // conv.bias
    %arg3: tensor<6x6x7x7xf32>     // input
) -> tensor<6x6x5x5xf32> {
  // 1. Convolution: input [N,C,H,W]=[6,6,7,7], weight [O,I,kH,kW]=[6,6,3,3], bias [O]=[6]
  // PyTorch Conv2d: stride=1, padding=0, dilation=1, groups=1
  // StableHLO: NCHW (b,f,0,1), OIHW (o,i,0,1)
  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x6x7x7xf32>, tensor<6x6x3x3xf32>) -> tensor<6x6x5x5xf32>

  // 2. Add bias: bias shape [6] -> broadcast to [6,6,5,5] along output channel
  // Bias is per-output-channel, so broadcast to [batch, channel, h, w] = [6,6,5,5]
  // We want to broadcast [6] to [6,6,5,5] along dim 1 (channel)
  // So broadcast_dimensions = [1]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x5x5xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x5x5xf32>

  // 3. Multiply by multiplier: multiplier shape [6,1,1] -> broadcast to [6,6,5,5] along channel
  // multiplier is per-channel, so broadcast [6,1,1] to [6,6,5,5] with broadcast_dimensions = [1,2,3]
  %mult_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1,2,3>} : (tensor<6x1x1xf32>) -> tensor<6x6x5x5xf32>
  %mul = stablehlo.multiply %conv_bias, %mult_broadcast : tensor<6x6x5x5xf32>

  // 4. LeakyReLU: y = x if x >= 0 else 0.01 * x
  // Compute mask: x >= 0
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %ge_mask = "stablehlo.compare"(%mul, %zero_bcast) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xi1>
  // Compute 0.01 * x
  %alpha = stablehlo.constant dense<0.01> : tensor<f32>
  %alpha_bcast = "stablehlo.broadcast_in_dim"(%alpha) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %mul_alpha = stablehlo.multiply %mul, %alpha_bcast : tensor<6x6x5x5xf32>
  // Select: if ge_mask then x else 0.01*x
  %leaky = "stablehlo.select"(%ge_mask, %mul, %mul_alpha) : (tensor<6x6x5x5xi1>, tensor<6x6x5x5xf32>, tensor<6x6x5x5xf32>) -> tensor<6x6x5x5xf32>

  // 5. GELU: y = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = stablehlo.constant dense<1.4142135> : tensor<f32>
  %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %x_div_sqrt2 = stablehlo.divide %leaky, %sqrt2_bcast : tensor<6x6x5x5xf32>
  // erf(x / sqrt(2))
  %erf = chlo.erf %x_div_sqrt2 : tensor<6x6x5x5xf32> -> tensor<6x6x5x5xf32>
  // 1 + erf(...)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %one_plus_erf = stablehlo.add %one_bcast, %erf : tensor<6x6x5x5xf32>
  // 0.5 * x
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x5x5xf32>
  %half_x = stablehlo.multiply %half_bcast, %leaky : tensor<6x6x5x5xf32>
  // Final GELU: 0.5 * x * (1 + erf(...))
  %gelu = stablehlo.multiply %half_x, %one_plus_erf : tensor<6x6x5x5xf32>

  return %gelu : tensor<6x6x5x5xf32>
}
