    %w_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // Now, dot_general: x [6,7], W^T [7,7], contract x:1 with W^T:0
    %linear = "stablehlo.dot_general"(
