  // Need to transpose bmm_weight to [7,7] -> [7,7] (no-op, but explicit for clarity)
  %wT = "stablehlo.transpose"(%bmm_weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // Dot: [6,7] x [7,7] -> [6,7]
  %xw = "stablehlo.dot_general"(%x, %wT) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // Add bias: bmm_bias [7] -> [6,7] via broadcast
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bmm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %xw_b = stablehlo.add %xw, %bias_bcast : tensor<6x7xf32>

  // InstanceNorm2d: treat each [6,7] row as a "channel" (N,C,H,W) = (6,7,1,1)
  // Reshape [6,7] -> [6,7,1,1]
  %xw_b_4d = stablehlo.reshape %xw_b : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Compute mean over spatial dims (2,3): [6,7,1,1] -> [6,7,1,1] (mean is just the value itself)
  // But for generality, reduce over (2,3)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%xw_b_4d, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
  // Divide by num elements (1*1=1), so mean = sum
  // Reshape mean to [6,7,1,1] for broadcasting
  %mean_4d = stablehlo.reshape %mean : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Subtract mean: [6,7,1,1] - [6,7,1,1]
  %centered = stablehlo.subtract %xw_b_4d, %mean_4d : tensor<6x7x1x1xf32>

  // Variance: mean((x - mean)^2) over (2,3)
  %centered_sq = stablehlo.multiply %centered, %centered : tensor<6x7x1x1xf32>
  %var = "stablehlo.reduce"(%centered_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x7xf32>
  // Divide by num elements (1*1=1), so var = sum
  %var_4d = stablehlo.reshape %var : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Add eps for numerical stability
  %eps = stablehlo.constant dense<1.0000000116860974E-5> : tensor<f32>
