  %std = stablehlo.sqrt %var_eps : tensor<6x7x1x1xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %normed = stablehlo.divide %centered, %std : tensor<6x7x1x1xf32>

  // Squeeze back to [6,7]
  %normed_2d = stablehlo.reshape %normed : (tensor<6x7x1x1xf32>) -> tensor<6x7xf32>

  // Add y: [6,7] + [6,7]
  %add = stablehlo.add %normed_2d, %y : tensor<6x7xf32>
  // Multiply by y: [6,7] * [6,7]
  %out = stablehlo.multiply %add, %y : tensor<6x7xf32>
  return %out : tensor<6x7xf32>
}
