    } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

    // --- Add conv.bias ---
    // conv.bias shape: [7] -> broadcast to [6,7,4,4] along dim 1
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x7x4x4xf32>

    // --- BatchNorm (training mode, use batch statistics) ---
    // Compute mean and variance over [N, H, W] for each channel (dim 0,2,3)
    // mean: shape [7]
    %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
    %mean = "stablehlo.reduce"(%conv_bias, %zero_f32) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>
    // Divide by N*H*W = 6*4*4 = 96
    %inv_count = stablehlo.constant dense<0.010416667> : tensor<f32> // 1/96
    %inv_count_bcast = "stablehlo.broadcast_in_dim"(%inv_count) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
    %mean = stablehlo.multiply %mean, %inv_count_bcast : tensor<7xf32>

    // Compute variance: mean((x - mean)^2)
    // Broadcast mean to [6,7,4,4]
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %centered = stablehlo.subtract %conv_bias, %mean_bcast : tensor<6x7x4x4xf32>
    %centered2 = stablehlo.multiply %centered, %centered : tensor<6x7x4x4xf32>
    %var = "stablehlo.reduce"(%centered2, %zero_f32) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>
    %var = stablehlo.multiply %var, %inv_count_bcast : tensor<7xf32>

    // Add epsilon for numerical stability (PyTorch default: 1e-5)
    %eps = stablehlo.constant dense<1.0000000116860974E-5> : tensor<f32>
    %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
    %var_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>

    // Compute invstd = 1 / sqrt(var + eps)
    %var_eps_sqrt = stablehlo.sqrt %var_eps : tensor<7xf32>
    %one_f32 = stablehlo.constant dense<1.0> : tensor<f32>
    %one_bcast = "stablehlo.broadcast_in_dim"(%one_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
    %invstd = stablehlo.divide %one_bcast, %var_eps_sqrt : tensor<7xf32>

    // BatchNorm: y = (x - mean) * invstd * gamma + beta
    // gamma: %arg2 [7], beta: %arg3 [7]
    %gamma_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %invstd_bcast = "stablehlo.broadcast_in_dim"(%invstd) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %bnorm = stablehlo.multiply %centered, %invstd_bcast : tensor<6x7x4x4xf32>
    %bnorm = stablehlo.multiply %bnorm, %gamma_bcast : tensor<6x7x4x4xf32>
    %beta_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
    %bnorm = stablehlo.add %bnorm, %beta_bcast : tensor<6x7x4x4xf32>

    // --- Scaling ---
    %scale = stablehlo.constant dense<2.0> : tensor<f32>
    %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7x4x4xf32>
    %out = stablehlo.multiply %bnorm, %scale_bcast : tensor<6x7x4x4xf32>

    return %out : tensor<6x7x4x4xf32>
  }
}
