func.func @main(
  %matmul_weight: tensor<16x16xf32>, 
  %matmul_bias: tensor<16xf32>, 
  %input: tensor<16x16xf32>
) -> tensor<16xf32> {
  // Matmul: x @ W^T + b
  // %input: [16,16], %matmul_weight: [16,16] (PyTorch Linear: out_features x in_features)
  // Need to do: dot_general(input, matmul_weight, contract input dim 1 with weight dim 1)
  // But PyTorch Linear uses weight [out, in], so we need to transpose weight to [in, out]
  %weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // Now: input [16,16], weight_t [16,16]
  // dot_general: contract input dim 1 with weight_t dim 0, result [16,16]
  %matmul = "stablehlo.dot_general"(
    %input, %weight_t
  ) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]
    >
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Add bias: bias [16] needs to be broadcast to [16,16] along dim 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%matmul_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %matmul_bias = stablehlo.add %matmul, %bias_broadcast : tensor<16x16xf32>

  // AvgPool1d with kernel_size=16, stride=16 (default), input [16,16] (batch, features)
  // PyTorch: x.unsqueeze(1) -> [16,1,16], avg_pool1d(kernel=16) -> [16,1,1], squeeze(1) -> [16,1]
  // So, reshape to [16,1,16]
  %pool_in = stablehlo.reshape %matmul_bias : (tensor<16x16xf32>) -> tensor<16x1x16xf32>
  // Reduce_window with window_dimensions=[1,1,16], window_strides=[1,1,16], padding=0
  // Initial value for sum: 0.0
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce_window"(%pool_in, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %s : tensor<f32>
  }) {
    window_dimensions = array<i64: 1, 1, 16>,
    window_strides = array<i64: 1, 1, 16>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>
  } : (tensor<16x1x16xf32>, tensor<f32>) -> tensor<16x1x1xf32>
  // Divide by 16.0 to get average
  %c16 = stablehlo.constant dense<16.0> : tensor<f32>
  %sum_reshaped = stablehlo.reshape %sum : (tensor<16x1x1xf32>) -> tensor<16xf32>
  %c16_broadcast = "stablehlo.broadcast_in_dim"(%c16) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16xf32>
  %avg = stablehlo.divide %sum_reshaped, %c16_broadcast : tensor<16xf32>
  // Restore shape to [16,1] for next ops
  %avg_reshaped = stablehlo.reshape %avg : (tensor<16xf32>) -> tensor<16x1xf32>

  // GELU: gelu(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  %c0_5 = stablehlo.constant dense<0.5> : tensor<f32>
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>
  %c2 = stablehlo.constant dense<2.0> : tensor<f32>
  %sqrt2 = stablehlo.sqrt %c2 : tensor<f32>
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x1xf32>
  %x_div_sqrt2 = stablehlo.divide %avg_reshaped, %sqrt2_broadcast : tensor<16x1xf32>
  %erf = chlo.erf %x_div_sqrt2 : tensor<16x1xf32> -> tensor<16x1xf32>
  %one_plus_erf = stablehlo.add %c1, %erf : tensor<16x1xf32>
  %x_times_one_plus_erf = stablehlo.multiply %avg_reshaped, %one_plus_erf : tensor<16x1xf32>
  %gelu = stablehlo.multiply %c0_5, %x_times_one_plus_erf : tensor<16x1xf32>

  // Scale: multiply by scale_factor=2.0
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x1xf32>
  %scaled = stablehlo.multiply %gelu, %scale_broadcast : tensor<16x1xf32>

