    %arg0: tensor<7x8x3x3xf32>,   // conv.weight [out_c, in_c, kH, kW]
    %arg1: tensor<7xf32>,         // conv.bias   [out_c]
    %arg2: tensor<6x8x8x8xf32>    // input       [N, in_c, H, W]
  ) -> tensor<6xf32> {
    // 1. Convolution: input [6,8,8,8], weight [7,8,3,3] (out_c, in_c, kH, kW)
    // Output: [6,7,6,6] (N, out_c, H_out, W_out)
    // NCHW: [N, C, H, W]
    // Kernel: [out_c, in_c, kH, kW]
    // dimension_numbers: [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]
    // window_strides = [1,1], padding = [[0,0],[0,0],[0,0],[0,0]], lhs_dilation = [1,1], rhs_dilation = [1,1]
    // But for 2D conv, spatial dims are last two: [2,3]
    // Padding: for kernel 3x3, PyTorch default is padding=0

    %conv = "stablehlo.convolution"(%arg2, %arg0) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

    // 2. Add bias: bias shape [7], need to broadcast to [6,7,6,6]
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>
    %conv_bias = stablehlo.add %conv, %bias_bcast : tensor<6x7x6x6xf32>

    // 3. AvgPool2d with kernel_size=4, stride=4, no padding
    // PyTorch: kernel_size=4, stride=4, padding=0
    // Reduce window over last two dims (H,W), window_dimensions = [1,1,4,4], window_strides = [1,1,4,4], padding = [[0,0],[0,0],[0,0],[0,0]]
    // For average, sum and divide by 16

    // Reduce window sum
    %c0 = stablehlo.constant dense<0.0> : tensor<f32>
    %window_sum = "stablehlo.reduce_window"(%conv_bias, %c0) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %s : tensor<f32>
    }) {
      window_dimensions = array<i64: 1, 1, 4, 4>,
      window_strides = array<i64: 1, 1, 4, 4>,
      base_dilations = array<i64: 1, 1, 1, 1>,
      window_dilations = array<i64: 1, 1, 1, 1>,
      padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
    } : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x7x2x2xf32>

    // Divide by 16.0 (pool window size)
    %c16 = stablehlo.constant dense<16.0> : tensor<f32>
    %window_avg = stablehlo.divide %window_sum, %c16 : tensor<6x7x2x2xf32>

    // 4. Sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
    %c1 = stablehlo.constant dense<1.0> : tensor<f32>
    %neg = stablehlo.negate %window_avg : tensor<6x7x2x2xf32>
    %exp = stablehlo.exponential %neg : tensor<6x7x2x2xf32>
    %denom = stablehlo.add %c1, %exp : tensor<6x7x2x2xf32>
    %sigmoid = stablehlo.divide %c1, %denom : tensor<6x7x2x2xf32>

    // 5. Sum over dims [1,2,3] (out_c, pooled_H, pooled_W) -> output shape [6]
    // Use reduce with init=0.0, dimensions=[1,2,3]
    %sum = "stablehlo.reduce"(%sigmoid, %c0) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %s = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %s : tensor<f32>
    }) {dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x2x2xf32>, tensor<f32>) -> tensor<6xf32>

    return %sum : tensor<6xf32>
  }
}
