  %23 = "stablehlo.broadcast_in_dim"(%c05) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %24 = stablehlo.multiply %17, %22 : tensor<6x7xf32>
  %25 = stablehlo.multiply %23, %24 : tensor<6x7xf32>

