  %26 = "stablehlo.broadcast_in_dim"(%c0f) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7xf32>
  %27 = stablehlo.maximum %25, %26 : tensor<6x7xf32>

